      if (type === "skill" && !String(task.skill ?? "").trim()) {
        throw new CronError("bad-request", "skill 类型任务必须选择 skill 名称");
      }
      if ((type === "agent") && !String(task.prompt ?? "").trim()) {
        throw new CronError("bad-request", "agent 类型任务必须填写提示词");
